// M2 V2 – nur offene Initiativ-Firmen aus M1 V2.
function clean(value) { return String(value ?? '').replace(/\u00a0/g, ' ').trim(); }
function wahr(value) { return ['true', 'wahr', 'ja', '1'].includes(clean(value).toLowerCase()); }
function optionen() {
  try { return $('02 – Vom Orchestrator starten').first().json || {}; } catch { return {}; }
}

const opts = optionen();
const testId = clean(opts._test_stellen_id);
const testLimit = Math.max(0, Number(opts._test_limit) || 0);
const allowFinished = opts._test_erlaube_fertig === true;
const kandidaten = [];

for (const item of $input.all()) {
  const row = item.json || {};
  const id = clean(row.stellen_id);
  const status = clean(row.m2_status).toUpperCase();
  if (!id || (testId && id !== testId)) continue;
  if (!allowFinished && status && status !== 'OFFEN') continue;
  if (clean(row.quelle).toLowerCase() !== 'agentursuche') continue;
  if (clean(row.record_type).toUpperCase() !== 'COMPANY') continue;
  if (!wahr(row._ist_initiativ)) continue;
  if (!clean(row.firma) || !clean(row.url)) continue;
  kandidaten.push({ json: { ...row, _m2_start_am: new Date().toISOString(), _test_stellen_id: testId,
    _test_limit: testLimit, _pipeline_stop_nach: clean(opts._pipeline_stop_nach).toUpperCase() } });
  if (testLimit > 0 && kandidaten.length >= testLimit) break;
}

return kandidaten;

const source = $('07 – Luna Request vorbereiten').item.json;
const response = $json;
const SCORES = ['score_fachlicher_fit','score_lernchance','score_umsetzung','score_technologie','score_breite','score_belegqualitaet'];
const FLAGS = ['reine_beratung_ohne_umsetzung','kein_agenturgeschaeft','praesenzpflicht_belegt','kein_marketing_ecommerce_bezug','kleinstanbieter_belegt','widerspruechliche_fehlerhafte_quellen'];
const TEXTE = ['fachlicher_fit','lernchance','umsetzungsnaehe','technologie_begruendung','breite_begruendung','belegqualitaet_begruendung','m2_begruendung','ablehnungsgrund','groesste_chance','groesstes_risiko'];

function errorText(v) { return typeof v === 'string' ? v : (v?.error?.message || v?.message || ''); }
function content(v) { const c=v?.choices?.[0]?.message?.content; return Array.isArray(c) ? c.map(x=>x?.text||x?.content||'').join('') : String(c||''); }
function normalize(v) {
  const r = {};
  for (const f of SCORES) { const n=Number(v?.[f]); if(!Number.isInteger(n)||n<0||n>5) throw new Error(`Ungueltiger Teilwert ${f}`); r[f]=n; }
  for (const f of FLAGS) { if(typeof v?.[f] !== 'boolean') throw new Error(`Ungueltige Flagge ${f}`); r[f]=v[f]; }
  r.confidence=String(v?.confidence||'').trim().toUpperCase();
  if(!['HOCH','MITTEL','NIEDRIG'].includes(r.confidence)) throw new Error('Ungueltige confidence');
  for(const f of TEXTE) r[f]=String(v?.[f]||'').replace(/\s+/g,' ').trim();
  return r;
}
function calculate(v) {
  const raw = v.score_fachlicher_fit*5 + v.score_lernchance*4 + v.score_umsetzung*3 +
    v.score_technologie*3 + v.score_breite*3 + v.score_belegqualitaet*2;
  let cap=100; const reasons=[];
  const deckel=(n,r)=>{cap=Math.min(cap,n);reasons.push(r);};
  if(v.reine_beratung_ohne_umsetzung) deckel(49,'reine Beratung ohne Umsetzung');
  if(v.kein_agenturgeschaeft) deckel(40,'kein Agenturgeschaeft (Verzeichnis, Portal, Hersteller, Konzern oder Vermittler)');
  if(v.praesenzpflicht_belegt) deckel(40,'ausdrueckliche Praesenzpflicht, kein Homeoffice');
  if(v.kein_marketing_ecommerce_bezug) deckel(54,'weder Marketing noch E-Commerce erkennbar');
  if(v.kleinstanbieter_belegt) deckel(44,'belegter Solo-/1–2-Personen-Anbieter');
  if(v.widerspruechliche_fehlerhafte_quellen) deckel(54,'widerspruechliche oder fehlerhafte Beleglage');
  const score=Math.round(Math.min(raw,cap));
  const status=score>=85?'SEHR_GUT':score>=70?'GEEIGNET':score>=55?'BEDINGT_GEEIGNET':'ABGELEHNT';
  let confidence=v.confidence;
  if(v.score_belegqualitaet<=1) confidence='NIEDRIG'; else if(v.score_belegqualitaet===2&&confidence==='HOCH') confidence='MITTEL';
  return {...v,matrix_rohwert:raw,matrix_deckel:cap,matrix_punktzahl:score,matrix_status:status,
    matrix_deckelgruende:reasons,confidence};
}

try {
  const apiError=errorText(response?.error?response:null); if(apiError) throw new Error(apiError);
  const raw=content(response); if(!raw) throw new Error('OpenAI hat keinen auswertbaren Inhalt geliefert.');
  const evaluation=calculate(normalize(JSON.parse(raw)));
  return {json:{...source,_miniEvaluation:evaluation,_route:'ok',_fallback_route:'direct',_used_model:'gpt-5.6-luna'}};
} catch(error) {
  return {json:{...source,_route:'error',_fallback_route:'none',_error_message:error.message,_attempted_model:'gpt-5.6-luna'}};
}

const row=$json; const e=row._miniEvaluation;
if(!e||!Number.isFinite(e.matrix_punktzahl)||!e.matrix_status) throw new Error('Keine gueltige M2-Bewertung vorhanden.');
const status=e.matrix_status;
const scoreLine=[`M2 ${row._m2_matrix_version||'FULL_SERVICE_V2_2026-09-07'}`,`Marketing/E-Commerce ${e.score_fachlicher_fit}/5`,
  `Lernumfeld ${e.score_lernchance}/5`,`Praxisbreite ${e.score_umsetzung}/5`,`Automation/KI ${e.score_technologie}/5`,
  `Einstiegschance ${e.score_breite}/5`,`Belege ${e.score_belegqualitaet}/5`,`final ${e.matrix_punktzahl}/100 (${status})`].join(' | ');
const caps=e.matrix_deckelgruende?.length?` Deckelung: ${e.matrix_deckelgruende.join('; ')} (max. ${e.matrix_deckel}).`:'';
let ablehnung=status==='ABGELEHNT'?(e.ablehnungsgrund||e.matrix_deckelgruende?.join('; ')||e.groesstes_risiko||'Unter 55 Punkten.'):'';
const clean={...row}; for(const k of ['_openai_request','_m2_system_prompt','_m2_firmen_text','_m2_schema','_miniEvaluation']) delete clean[k];
return {json:{...clean,m2_status:status,m2_fachlicher_status:status,bewertung:e.matrix_punktzahl,confidence:e.confidence,
  fachlicher_fit:`[${e.score_fachlicher_fit}/5 Marketing/E-Commerce] ${e.fachlicher_fit}`.trim(),
  lernchance:`[${e.score_lernchance}/5 Lernumfeld] ${e.lernchance}`.trim(),
  umsetzungsnaehe:`[${e.score_umsetzung}/5 Praxisbreite] ${e.umsetzungsnaehe}`.trim(),
  m2_begruendung:`${scoreLine}. ${e.m2_begruendung}${caps}`.trim(),ablehnungsgrund:ablehnung,
  groesste_chance:e.groesste_chance,groesstes_risiko:e.groesstes_risiko,m2_bewertet_am:new Date().toISOString(),
  m2_fehler:false,m2_fehlertext:'',m2_fehler_am:'',_weitergabe_an_m3:status!=='ABGELEHNT',_ki_call:'gpt-5.6-luna',_ki_erfolg:true,
  _m2_matrix_version:row._m2_matrix_version||'FULL_SERVICE_V2_2026-09-07',_m2_teilwerte:{full_service:e.score_fachlicher_fit,
    lernumfeld:e.score_lernchance,praxisbreite:e.score_umsetzung,automation_ki:e.score_technologie,business_bruecke:e.score_breite,belege:e.score_belegqualitaet}}};

const row = $json;

const cleanRow = Object.assign({}, row);
delete cleanRow._openai_request;
delete cleanRow._m2_system_prompt;
delete cleanRow._m2_firmen_text;
delete cleanRow._m2_schema;
delete cleanRow._miniEvaluation;
delete cleanRow._finalEvaluation;

return {
  json: Object.assign({}, cleanRow, {
    m2_status: 'OFFEN',
    m2_fehler: true,
    m2_fehlertext: String(row._error_message || 'Unbekannter M2-Fehler').trim(),
    m2_fehler_am: new Date().toISOString(),
    _weitergabe_an_m3: false,
    _ki_call: row._attempted_model || 'gpt-5.6-luna',
    _ki_erfolg: false
  })
};

// M2 - Laufzusammenfassung.
// Holt Stammdaten wie Firma und URL anhand stellen_id wieder aus Node 04,
// weil der Google-Sheets-Update-Node 16 nur die geschriebenen M2-Felder zurückgibt.

const items = $input.all();
const originalItems = $('04 – Neue Agenturen auswählen').all();

const WEITERGABE = new Set([
  'SEHR_GUT',
  'GEEIGNET',
  'BEDINGT_GEEIGNET'
]);

const ALLE = new Set([
  'SEHR_GUT',
  'GEEIGNET',
  'BEDINGT_GEEIGNET',
  'ABGELEHNT'
]);

// Originaldaten aus Node 04 nach stellen_id merken
const originalMap = new Map();

for (const item of originalItems) {
  const row = item.json || {};
  const id = String(row.stellen_id || '').trim();

  if (id) {
    originalMap.set(id, row);
  }
}

function clean(value) {
  return String(value ?? '').trim();
}

function parseTeilwerte(text) {
  const value = clean(text);

  function get(label) {
    const match = value.match(
      new RegExp(`${label}\\s+([0-5](?:\\.5)?)/5`, 'i')
    );

    return match ? Number(match[1]) : null;
  }

  return {
    full_service: get('Marketing/E-Commerce'),
    praxisbreite: get('Praxisbreite'),
    lernumfeld: get('Lernumfeld'),
    automation_ki: get('Automation/KI'),
    belegqualitaet: get('Belege'),
    business_bruecke: get('Einstiegschance')
  };
}

function parseMatrixVersion(text) {
  const match = clean(text).match(
    /M2\s+([^|]+)/i
  );

  return match ? match[1].trim() : 'FULL_SERVICE_V2_2026-09-07';
}

let erfolgreich = 0;
let fehler = 0;

const verteilung = {};
const weitergabe = [];
const abgelehnt = [];

for (const item of items) {
  const row = item.json || {};

  const stellenId = clean(row.stellen_id);
  const original = originalMap.get(stellenId) || {};

  const status = clean(row.m2_status).toUpperCase();

  if (!ALLE.has(status)) {
    fehler += 1;
    continue;
  }

  erfolgreich += 1;
  verteilung[status] = (verteilung[status] || 0) + 1;

  const begruendung = clean(row.m2_begruendung);

  const eintrag = {
    stellen_id: stellenId,

    // Stammdaten sicher aus Node 04 holen
    firma: clean(row.firma) || clean(original.firma),
    url: clean(row.url) || clean(original.url),
    ort: clean(row.ort) || clean(original.ort),

    m2_status: status,
    bewertung: row.bewertung,
    confidence: clean(row.confidence),
    m2_begruendung: begruendung,

    m2_matrix_version:
      clean(row._m2_matrix_version) ||
      parseMatrixVersion(begruendung),

    m2_teilwerte:
      row._m2_teilwerte &&
      Object.keys(row._m2_teilwerte).length
        ? row._m2_teilwerte
        : parseTeilwerte(begruendung),

    ki_pruefung: clean(row._ki_call)
  };

  if (WEITERGABE.has(status)) {
    weitergabe.push(eintrag);
  } else {
    abgelehnt.push({
      ...eintrag,
      ablehnungsgrund: clean(row.ablehnungsgrund)
    });
  }
}

return [{
  json: {
    workflow: 'M2 – Agenturbewertung Initiativ',
    status: fehler > 0 ? 'MIT_FEHLERN' : 'ERFOLGREICH',
    quelle: 'Agentursuche',

    verarbeitete_firmen: items.length,
    erfolgreich_bewertet: erfolgreich,
    weitergegeben_an_m3: weitergabe.length,
    abgelehnt: abgelehnt.length,
    fehler,

    verteilung,
    weitergabe,
    abgelehnte_firmen: abgelehnt,

    _pipeline_stop_nach: clean(originalItems[0]?.json?._pipeline_stop_nach).toUpperCase(),
    _test_stellen_id: clean(originalItems[0]?.json?._test_stellen_id),

    beendet_am: new Date().toISOString()
  }
}];
